const dgram = require('dgram');
const crypto = require('crypto');
const { Buffer } = require('buffer');

class TenantDNSResolver {
  constructor() {
    this.tenants = new Map();
    this.queryPool = new Map();
    this.recycleQueue = [];
    this.maxPoolSize = 1024;
  }

  registerTenant(tenantId, config) {
    const tenant = {
      id: tenantId,
      upstream: config.upstream || '8.8.8.8',
      cache: new Map(),
      rateLimit: { count: 0, window: Date.now(), max: config.maxQPS || 100 },
      queryRefs: new Set()
    };
    this.tenants.set(tenantId, tenant);
    return tenant;
  }

  allocQueryContext(tenantId, domain) {
    const queryId = crypto.randomBytes(2).readUInt16BE(0);
    let ctx;
    if (this.recycleQueue.length > 0) {
      ctx = this.recycleQueue.pop();
      ctx.queryId = queryId;
      ctx.tenantId = tenantId;
      ctx.domain = domain;
      ctx.state = 'allocated';
      ctx.refCount = 1;
      ctx.timestamp = Date.now();
    } else {
      ctx = {
        queryId,
        tenantId,
        domain,
        state: 'allocated',
        refCount: 1,
        timestamp: Date.now(),
        responseBuffer: Buffer.alloc(512)
      };
    }
    this.queryPool.set(queryId, ctx);
    const tenant = this.tenants.get(tenantId);
    if (tenant) tenant.queryRefs.add(queryId);
    return ctx;
  }

  retainContext(queryId) {
    const ctx = this.queryPool.get(queryId);
    if (ctx && ctx.state === 'allocated') {
      ctx.refCount++;
      return ctx;
    }
    return null;
  }

  releaseContext(queryId) {
    const ctx = this.queryPool.get(queryId);
    if (!ctx) return;
    ctx.refCount--;
    if (ctx.refCount <= 0) {
      this._freeContext(ctx);
    }
  }

  _freeContext(ctx) {
    const tenant = this.tenants.get(ctx.tenantId);
    if (tenant) tenant.queryRefs.delete(ctx.queryId);
    this.queryPool.delete(ctx.queryId);
    ctx.state = 'freed';
    if (this.recycleQueue.length < this.maxPoolSize) {
      this.recycleQueue.push(ctx);
    }
  }

  async resolve(tenantId, domain) {
    const tenant = this.tenants.get(tenantId);
    if (!tenant) throw new Error('Unknown tenant');
    if (!this._checkRateLimit(tenant)) throw new Error('Rate limited');

    const cached = tenant.cache.get(domain);
    if (cached && cached.expiry > Date.now()) return cached.records;

    const ctx = this.allocQueryContext(tenantId, domain);

    try {
      const result = await this._sendQuery(ctx, tenant);
      tenant.cache.set(domain, { records: result, expiry: Date.now() + 300000 });
      return result;
    } finally {
      this.releaseContext(ctx.queryId);
    }
  }

  async _sendQuery(ctx, tenant) {
    return new Promise((resolve, reject) => {
      const socket = dgram.createSocket('udp4');
      const packet = this._buildPacket(ctx);
      const timeoutId = setTimeout(() => {
        this.releaseContext(ctx.queryId);
        socket.close();
        reject(new Error('DNS timeout'));
      }, 5000);

      socket.on('message', (msg) => {
        clearTimeout(timeoutId);
        const responseId = msg.readUInt16BE(0);
        const activeCtx = this.queryPool.get(responseId);
        if (activeCtx && activeCtx.tenantId === ctx.tenantId) {
          msg.copy(activeCtx.responseBuffer, 0, 0, Math.min(msg.length, 512));
          const records = this._parseResponse(activeCtx.responseBuffer);
          socket.close();
          resolve(records);
        } else {
          socket.close();
          reject(new Error('Mismatched response'));
        }
      });

      socket.on('error', (err) => {
        clearTimeout(timeoutId);
        socket.close();
        reject(err);
      });

      socket.send(packet, 53, tenant.upstream);
    });
  }

  _buildPacket(ctx) {
    const buf = Buffer.alloc(512);
    buf.writeUInt16BE(ctx.queryId, 0);
    buf.writeUInt16BE(0x0100, 2);
    buf.writeUInt16BE(1, 4);
    let offset = 12;
    const parts = ctx.domain.split('.');
    for (const part of parts) {
      buf.writeUInt8(part.length, offset++);
      buf.write(part, offset, part.length, 'ascii');
      offset += part.length;
    }
    buf.writeUInt8(0, offset++);
    buf.writeUInt16BE(1, offset);
    buf.writeUInt16BE(1, offset + 2);
    return buf.slice(0, offset + 4);
  }

  _parseResponse(buf) {
    const ancount = buf.readUInt16BE(6);
    const records = [];
    let offset = 12;
    while (offset < buf.length && buf[offset] !== 0) offset += buf[offset] + 1;
    offset += 5;
    for (let i = 0; i < ancount && offset + 12 <= buf.length; i++) {
      if ((buf[offset] & 0xC0) === 0xC0) offset += 2;
      else { while (offset < buf.length && buf[offset] !== 0) offset += buf[offset] + 1; offset++; }
      const rdlength = buf.readUInt16BE(offset + 8);
      if (buf.readUInt16BE(offset) === 1 && rdlength === 4) {
        const ip = `${buf[offset+10]}.${buf[offset+11]}.${buf[offset+12]}.${buf[offset+13]}`;
        records.push(ip);
      }
      offset += 10 + rdlength;
    }
    return records;
  }

  _checkRateLimit(tenant) {
    const now = Date.now();
    if (now - tenant.rateLimit.window > 1000) {
      tenant.rateLimit.count = 0;
      tenant.rateLimit.window = now;
    }
    return ++tenant.rateLimit.count <= tenant.rateLimit.max;
  }

  evictTenant(tenantId) {
    const tenant = this.tenants.get(tenantId);
    if (!tenant) return;
    for (const queryId of tenant.queryRefs) {
      this.releaseContext(queryId);
    }
    this.tenants.delete(tenantId);
  }
}

module.exports = { TenantDNSResolver };
